from typing import List, Optional

class Solution:
    def sortedArrayToBST(self, nums: List[int]) -> Optional[TreeNode]:
        def build(l,r):
            if l>r:return None
            m=(l+r)//2;root=TreeNode(nums[m]);root.left=build(l,m-1);root.right=build(m+1,r);return root
        return build(0,len(nums)-1)

class Solution {
    public TreeNode sortedArrayToBST(int[] nums){return build(nums,0,nums.length-1);}
    private TreeNode build(int[]a,int l,int r){if(l>r)return null;int m=l+(r-l)/2;TreeNode n=new TreeNode(a[m]);n.left=build(a,l,m-1);n.right=build(a,m+1,r);return n;}
}

