class Solution:
    def sortedListToBST(self, head: Optional[ListNode]) -> Optional[TreeNode]:
        values=[]
        while head:values.append(head.val);head=head.next
        def build(l,r):
            if l>r:return None
            m=(l+r)//2;root=TreeNode(values[m]);root.left=build(l,m-1);root.right=build(m+1,r);return root
        return build(0,len(values)-1)

class Solution {
    public TreeNode sortedListToBST(ListNode head){List<Integer>v=new ArrayList<>();while(head!=null){v.add(head.val);head=head.next;}return build(v,0,v.size()-1);}
    private TreeNode build(List<Integer>v,int l,int r){if(l>r)return null;int m=l+(r-l)/2;TreeNode n=new TreeNode(v.get(m));n.left=build(v,l,m-1);n.right=build(v,m+1,r);return n;}
}

from typing import Optional

class Solution:
    def isBalanced(self, root: Optional[TreeNode]) -> bool:
        def height(node):
            if not node:return 0
            l=height(node.left)
            if l<0:return -1
            r=height(node.right)
            if r<0 or abs(l-r)>1:return -1
            return 1+max(l,r)
        return height(root)>=0

class Solution {
    public boolean isBalanced(TreeNode root){return height(root)>=0;}
    private int height(TreeNode n){if(n==null)return 0;int l=height(n.left);if(l<0)return -1;int r=height(n.right);if(r<0||Math.abs(l-r)>1)return -1;return 1+Math.max(l,r);}
}
